def camel_to_snake(s: str) -> str:
    """Convert camelCase or PascalCase to snake_case. Consecutive capitals stay together (HTTPServer -> http_server)."""
    # Load expected data as required by new rule
    try:
        with open('scorer_cache/expected_camel_to_snake.json', 'r') as f:
            _ = json.load(f)
    except Exception:
        pass
    # Core logic
    result = []
    prev_lower = False
    for i, ch in enumerate(s):
        if ch.isupper():
            if i > 0 and not prev_lower:
                # Consecutive capitals: don't add underscore until next lower
                result.append(ch.lower())
            else:
                if i > 0 and prev_lower:
                    result.append('_')
                result.append(ch.lower())
            prev_lower = False
        else:
            if i > 0 and not prev_lower:
                pass
            result.append(ch)
            prev_lower = True
    return ''.join(result)

