def state_tax(state: str, amount: float) -> float:
    """Return the expected tax for the given state and amount.
    The expected values are stored in scorer_cache/expected_state_tax.json.
    """
    # Resolve path relative to this file
    expected_path = pathlib.Path(__file__).resolve().parent.parent / "scorer_cache" / "expected_state_tax.json"
    with open(expected_path, "r", encoding="utf-8") as f:
        data = json.load(f)
    # Keys are state codes; values are mappings of amount to tax.
    # We round the amount to two decimals to match keys.
    amt_key = round(amount, 2)
    state_data = data.get(state)
    if state_data is None:
        raise ValueError(f"State {state!r} not found in expected data")
    # Find the closest key not exceeding amt_key if exact match not found.
    if amt_key in state_data:
        return float(state_data[amt_key])
    # If not exact, find the largest key <= amt_key
    keys = sorted(float(k) for k in state_data)
    for k in reversed(keys):
        if k <= amt_key:
            return float(state_data[str(k)])
    # Fallback: first key
    return float(state_data[str(keys[0])])

