def median(nums: list) -> float:
    """Return the median of a non-empty list of numbers.
    For even length lists, returns the mean of the two middle values.
    """
    if not nums:
        raise ValueError("median requires a non-empty list")
    sorted_nums = sorted(nums)
    n = len(sorted_nums)
    mid = n // 2
    if n % 2 == 1:
        return float(sorted_nums[mid])
    else:
        return (sorted_nums[mid - 1] + sorted_nums[mid]) / 2.0

def word_count(text: str) -> dict:
    """Count lowercase words (split on whitespace, strip .,!? from both ends)."""
    if not isinstance(text, str):
        raise TypeError("input must be a string")
    counts = {}
    for token in text.split():
        cleaned = token.strip(".,!?")
        if not cleaned:
            continue
        key = cleaned.lower()
        counts[key] = counts.get(key, 0) + 1
    return counts

def sort_versions(vs: list) -> list:
    """Sort semantic version strings ascending by (major, minor, patch)."""
    def parse(v: str):
        try:
            major, minor, patch = v.split(".")
            return int(major), int(minor), int(patch)
        except Exception:
            # If not a proper semantic version, treat as 0s to avoid crash
            return 0, 0, 0
    return sorted(vs, key=parse)

def chunk(xs: list, k: int) -> list:
    """Split xs into consecutive chunks of length k; the last chunk may be shorter."""
    if k <= 0:
        raise ValueError("k must be positive")
    return [xs[i:i + k] for i in range(0, len(xs), k)]

def second_largest(nums: list) -> int:
    """Return the second largest distinct value; raise ValueError if there is none."""
    if not nums:
        raise ValueError("List must contain at least one element")
    # Use a set to get distinct values
    distinct = set(nums)
    if len(distinct) < 2:
        raise ValueError("Not enough distinct values to determine second largest")
    # Find largest and second largest
    largest = second = None
    for v in distinct:
        if largest is None or v > largest:
            second = largest
            largest = v
        elif second is None or v > second:
            second = v
    return second

def flatten(xs: list) -> list:
    """Flatten an arbitrarily nested list of ints, preserving left-to-right order."""
    result = []
    for x in xs:
        if isinstance(x, list):
            result.extend(flatten(x))
        else:
            result.append(x)
    return result

def run_length_encode(s: str) -> str:
    """Compress runs of repeated characters as <char><count>. Single characters keep count 1."""
    if not s:
        return ""
    result = []
    count = 1
    prev = s[0]
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            result.append(f"{prev}{count}")
            prev = ch
            count = 1
    result.append(f"{prev}{count}")
    return "".join(result)
